describe('Duplicate Record Functionality', () => {
    beforeEach(() => {
        cy.visit('/records'); // Adjust the URL to your application's records page
        cy.get('.record-item').first().as('firstRecord'); // Assuming records have a class of 'record-item'
    });

    it('should duplicate an existing record successfully', () => {
        cy.get('@firstRecord').find('.duplicate-button').click(); // Assuming there's a button with class 'duplicate-button'
        cy.get('.confirmation-message').should('be.visible').and('contain', 'Record duplicated successfully'); // Check for success message
        cy.get('.record-item').should('have.length', 2); // Verify that the record count has increased
    });

    it('should show an error message when duplication fails', () => {
        cy.intercept('POST', '/api/records/duplicate', { statusCode: 500 }).as('duplicateError'); // Simulate a server error
        cy.get('@firstRecord').find('.duplicate-button').click();
        cy.wait('@duplicateError');
        cy.get('.error-message').should('be.visible').and('contain', 'Failed to duplicate record'); // Check for error message
    });
});
